/**
 * Offline CPU/GPU model comparison.
 *
 * `hardware-scores.json` is generated by `scripts/build-hardware-scores.mjs`
 * from Blender Open Data (CC0). The score is Cycles render performance, not a
 * game benchmark, so it is only a coarse relative proxy: a clear lead counts
 * as a match, a close model stays partial, and anything far below only fails
 * on a wide margin. Nothing here reads the network.
 *
 * The key extraction mirrors the generator. When a naming rule changes there,
 * change it here too and regenerate the table.
 */

import scores from "./hardware-scores.json";

export type HardwareKind = "cpu" | "gpu";
export type ScoreVerdict = "ok" | "partial" | "fail";

/**
 * Blender scores exaggerate generation gaps and say nothing about a specific
 * engine. A detected part has to be effectively as fast as the requirement to
 * claim a match, and has to be less than half as fast before the row says the
 * game cannot run.
 */
const MEETS_RATIO = 0.95;
const PARTIAL_RATIO = 0.5;

const TABLES: Record<HardwareKind, Map<string, number>> = {
  gpu: new Map(scores.gpus.map((row) => [row.key, row.score])),
  cpu: new Map(scores.cpus.map((row) => [row.key, row.score])),
};

function normalize(value: string): string {
  return value
    .toLowerCase()
    .replace(/\(r\)|\(tm\)/g, " ")
    .replace(/\b\d+\s?(?:gb|mb)\b/g, " ")
    .replace(/@.*$/g, " ")
    .replace(
      /\b(cpu|processor|graphics|series|gpu|laptop gpu|mobile gpu|max-q|max q|with max-q design)\b/g,
      (match) => (match.includes("laptop") ? "laptop" : match.includes("max") ? "maxq" : " "),
    )
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function gpuKeys(name: string): string[] {
  const n = normalize(name);
  const keys = new Set<string>();
  for (const match of n.matchAll(
    /\b(rtx|gtx|gt)\s*(\d{3,4})\s*(ti|super|laptop|mobile|maxq)?\s*(laptop|mobile|maxq)?/g,
  )) {
    keys.add([match[1], match[2], match[3], match[4]].filter(Boolean).join(" "));
  }
  for (const match of n.matchAll(
    /\b(rx|hd)\s*(\d{3,4})\s*(xtx|xt|gre|super|laptop|mobile)?/g,
  )) {
    keys.add([match[1], match[2], match[3]].filter(Boolean).join(" "));
  }
  for (const match of n.matchAll(/\barc\s*([ab])\s*(\d{3})\b/g)) {
    keys.add(`arc ${match[1]}${match[2]}`);
  }
  if (/\biris\s*xe\b/.test(n)) keys.add("iris xe");
  for (const match of n.matchAll(/\bvega (\d{1,2})\b/g)) {
    keys.add(`vega ${match[1]}`);
  }
  // RDNA2/RDNA3 integrated GPUs ("Radeon 680M").
  for (const match of n.matchAll(/\bradeon (\d{3})m\b/g)) {
    keys.add(`radeon ${match[1]}m`);
  }
  for (const match of n.matchAll(/\b(uhd|hd)\s*(\d{3})\b/g)) {
    keys.add(`${match[1]} ${match[2]}`);
  }
  return [...keys];
}

function cpuKeys(name: string): string[] {
  const n = normalize(name);
  const keys = new Set<string>();
  for (const match of n.matchAll(/\bi([3579])[- ]?(\d{4,5}[a-z]*)\b/g)) {
    keys.add(`i${match[1]}-${match[2]}`);
  }
  // Core 2 (2006-2009). Desktop models carry an E/Q prefix, but Windows also
  // reports "Core2 CPU 6300" for an E6300, so a bare number becomes E-series.
  // Rows also spell the model apart from the family ("Core2 Duo 1.86 GHz
  // (E6300)"), so the model code is searched across the whole name.
  if (/\bcore\s*2\b/.test(n)) {
    const model =
      /\b([eqptx]\d{3,4}[a-z]?)\b/.exec(n) ??
      /\bcore\s*2\b(?:\s*(?:duo|quad|extreme))?\s*(?:cpu\s*)?(\d{4})\b/.exec(n);
    keys.add(model ? `core 2 ${/^\d/.test(model[1]) ? `e${model[1]}` : model[1]}` : "core 2");
  }
  // Athlon 64 X2 (2005-2007); the model number can follow "Dual Core".
  for (const match of n.matchAll(
    /\bathlon\s*64\s*x2\b(?:\s*dual core)?(?:\s*(\d{3,4}))?/g,
  )) {
    keys.add(match[1] ? `athlon 64 x2 ${match[1]}` : "athlon 64 x2");
  }
  // Athlon II X2/X3/X4 (2009-2011).
  for (const match of n.matchAll(
    /\bathlon\s*ii\s*x([234])\b(?:\s*(\d{3,4}[a-z]?))?/g,
  )) {
    keys.add(match[2] ? `athlon ii x${match[1]} ${match[2]}` : `athlon ii x${match[1]}`);
  }
  // Athlon X4 (2013-2015) and the 200GE/3000G line.
  for (const match of n.matchAll(
    /\bathlon\s*x([234])\b(?:\s*(\d{3,4}[a-z]?))?/g,
  )) {
    keys.add(match[2] ? `athlon x${match[1]} ${match[2]}` : `athlon x${match[1]}`);
  }
  for (const match of n.matchAll(/\bathlon\s+(\d{3,4}[a-z]{0,2})\b/g)) {
    keys.add(`athlon ${match[1]}`);
  }
  // Phenom II X2/X3/X4/X6 (2009-2011).
  for (const match of n.matchAll(
    /\bphenom\s*ii\s*x([2346])\b(?:\s*(\d{3,4}[a-z]?))?/g,
  )) {
    keys.add(match[2] ? `phenom ii x${match[1]} ${match[2]}` : `phenom ii x${match[1]}`);
  }
  // FX-4300..FX-9590. The FX APUs are reported with "Radeon" and are skipped
  // as GPUs before this runs.
  for (const match of n.matchAll(/\bfx\s*(\d{4}[a-z]?)\b/g)) {
    keys.add(`fx ${match[1]}`);
  }
  for (const match of n.matchAll(/\bultra ([3579]) (\d{3}[a-z]*)\b/g)) {
    keys.add(`ultra ${match[1]} ${match[2]}`);
  }
  // The "Core 7 150U" rebrand has no i-prefix.
  for (const match of n.matchAll(/\bcore ([3579]) (\d{3}[a-z]*)\b/g)) {
    keys.add(`core ${match[1]} ${match[2]}`);
  }
  for (const match of n.matchAll(/\bryzen ([3579]) (\d{4}[a-z]*)\b/g)) {
    keys.add(`ryzen ${match[1]} ${match[2]}`);
  }
  for (const match of n.matchAll(/\bryzen ai ([3579])(?: pro)? (?:h )?(\d{3}[a-z]*)\b/g)) {
    keys.add(`ryzen ai ${match[1]} ${match[2]}`);
  }
  for (const match of n.matchAll(/\bapple m([1-9])(?: (pro|max|ultra))?/g)) {
    keys.add(`apple m${match[1]}${match[2] ? ` ${match[2]}` : ""}`);
  }
  return [...keys];
}

/** Family rows: the weakest member is the threshold a store row implies. */
const CPU_FAMILIES = [
  "core 2",
  "athlon 64 x2",
  "athlon ii x2",
  "athlon ii x3",
  "athlon ii x4",
  "athlon x2",
  "athlon x3",
  "athlon x4",
  "phenom ii x2",
  "phenom ii x3",
  "phenom ii x4",
  "phenom ii x6",
  "fx",
];

/** The family a key belongs to, longest match first ("phenom ii x4 955"
 *  belongs to "phenom ii x4", not to "phenom"). */
function cpuFamilyOf(key: string): string | null {
  let family: string | null = null;
  for (const candidate of CPU_FAMILIES) {
    if (key !== candidate && !key.startsWith(`${candidate} `)) continue;
    if (!family || candidate.length > family.length) family = candidate;
  }
  return family;
}

/** Table score for a device name, or null when the model is not listed. */
export function hardwareScore(kind: HardwareKind, name: string): number | null {
  if (!name) return null;
  // The longest key is the most specific one: "rtx 5070 laptop" before a
  // base "rtx 5070" alias.
  const keys = (kind === "gpu" ? gpuKeys(name) : cpuKeys(name)).sort(
    (a, b) => b.length - a.length,
  );
  for (const key of keys) {
    const score = TABLES[kind].get(key);
    if (score !== undefined) return score;
  }
  // A store row can name a model the table only knows by family ("Athlon 64
  // X2 4050+" next to the 4800+ entry); the family row is the floor.
  if (kind === "cpu") {
    for (const key of keys) {
      const family = cpuFamilyOf(key);
      const score = family ? TABLES.cpu.get(family) : undefined;
      if (score !== undefined) return score;
    }
  }
  return null;
}

/** Splits "A / B or C" into model names so every alternative is considered. */
function requirementChunks(text: string): string[] {
  return text
    .split(
      /\s*(?:\/|,|;|&|\+|r?\n|\bor\b|\bveya\b|\bve\b|\bya da\b|\boder\b|\bou\b|\bo\b|\by\b|\band\b)\s*/i,
    )
    .map((chunk) => chunk.trim())
    .filter(Boolean);
}

/**
 * Compares a detected model with the models named in one requirement row.
 * The lowest listed score is the threshold, so the easiest alternative wins,
 * matching how the numeric checks treat multiple values. Null means the table
 * cannot answer and the caller keeps its old partial/manual behavior.
 */
export function compareHardwareScore(
  kind: HardwareKind,
  detectedName: string,
  requiredText: string,
): ScoreVerdict | null {
  const detected = hardwareScore(kind, detectedName);
  if (detected === null) return null;
  const alternatives = requirementChunks(requiredText)
    .map((chunk) => hardwareScore(kind, chunk))
    .filter((score): score is number => score !== null && score > 0);
  if (alternatives.length === 0) return null;
  const required = Math.min(...alternatives);
  const ratio = detected / required;
  if (ratio >= MEETS_RATIO) return "ok";
  if (ratio >= PARTIAL_RATIO) return "partial";
  return "fail";
}
